-- Paid grammar lessons B1, B2, C1 (A1 and A2 are free and inside index.html).
-- Run in Supabase > SQL Editor AFTER schema.sql. Safe to run again (it updates existing rows).
-- Keep this file PRIVATE: it contains paid content.
insert into public.premium_content (key, kind, payload) values
('grammar-b1', 'grammar', $j${"level":"B1","topics":[{"id":"b1-adjektiv","level":"B1","title":"Adjektivendungen","en":"Adjective endings","intro":["An adjective before a noun gets an ending. The ending depends on gender, case and on the article before it.","After der/die/das (definite article) the nominative singular ends in -e and the accusative of feminine and neuter also in -e; everything else is -en. After ein/eine (indefinite article) the nominative masculine ends in -er, neuter in -es, feminine in -e.","Without an article the adjective shows the case itself: gutes Wetter, frischer Kaffee, kalte Milch."],"ex":[["Das ist ein interessantes Buch.","That is an interesting book."],["Ich trinke einen starken Kaffee.","I drink a strong coffee."],["Sie hat eine neue Wohnung.","She has a new flat."],["Wir besuchen unsere alten Freunde.","We visit our old friends."]],"q":[["Das ist ein neu___ Auto.",["e","er","es","en"],2,"Neuter nominative after ein: -es."],["Ich kaufe einen rot___ Pullover.",["en","e","er","es"],0,"Masculine accusative after einen: -en."],["Die klein___ Kinder spielen.",["e","en","er","es"],1,"Plural after die: -en."],["Sie trägt eine schön___ Jacke.",["e","en","er","es"],0,"Feminine nominative/accusative after eine: -e."],["Das ist ein gut___ Arzt.",["er","en","e","es"],0,"Masculine nominative after ein: -er."]],"table":[["Nominativ","der-Wort","ein-Wort"],["maskulin","der gute Arzt","ein guter Arzt"],["feminin","die gute Ärztin","eine gute Ärztin"],["neutral","das gute Buch","ein gutes Buch"],["Plural","die guten Bücher","gute Bücher"]]},{"id":"b1-praeteritum","level":"B1","title":"Präteritum","en":"Simple past","intro":["The Präteritum is used mostly in writing (news, stories) and for sein, haben and the modal verbs even in speech: ich war, ich hatte, ich konnte.","Regular verbs: stem + -te: machen → ich machte. Irregular verbs change the stem: gehen → ging, kommen → kam, sehen → sah. Ich and er/sie/es have the same form with no ending."],"ex":[["Gestern war ich beim Zahnarzt.","Yesterday I was at the dentist."],["Er hatte keine Zeit.","He had no time."],["Wir konnten nicht kommen.","We could not come."],["Sie ging nach Hause und las ein Buch.","She went home and read a book."]],"q":[["Letztes Jahr ___ wir in Spanien.",["waren","sind","war","wart"],0,"Präteritum of sein: wir waren."],["Ich ___ gestern keine Zeit.",["habe","hatte","hatten","gehabt"],1,"Präteritum of haben: ich hatte."],["Er ___ den Termin nicht wahrnehmen. (können)",["kann","konnte","gekonnt","könnte"],1,"Präteritum of können: er konnte."],["Sie ___ nach Hause. (gehen)",["geht","gegangen","ging","gingen"],2,"Irregular: gehen → ging."],["Die Lehrerin ___ die Aufgabe. (erklären, regelmäßig)",["erklärte","erklärt","erklärten","erklärst"],0,"Regular: stem + te."]],"table":[["","sein","haben","können","gehen"],["ich","war","hatte","konnte","ging"],["du","warst","hattest","konntest","gingst"],["er/sie/es","war","hatte","konnte","ging"],["wir","waren","hatten","konnten","gingen"]]},{"id":"b1-relativ","level":"B1","title":"Relativsätze","en":"Relative clauses","intro":["A relative clause gives more information about a noun. It starts with a relative pronoun (der, die, das, den, dem, ...) and the verb goes to the end. It is separated by commas.","The pronoun agrees with the noun in gender and number, but its case depends on its role inside the relative clause: Der Mann, der dort steht, ... (subject, nominative). Der Mann, den ich kenne, ... (object, accusative). Der Mann, dem ich helfe, ... (dative)."],"ex":[["Das ist der Arzt, der mir geholfen hat.","That is the doctor who helped me."],["Die Frau, die ich gestern getroffen habe, ist Lehrerin.","The woman whom I met yesterday is a teacher."],["Das Buch, das ich lese, ist spannend.","The book I am reading is exciting."],["Das sind die Kollegen, mit denen ich arbeite.","Those are the colleagues I work with."]],"q":[["Der Mann, ___ dort steht, ist mein Chef.",["den","der","dem","das"],1,"The man is the subject of 'steht': nominative masculine: der."],["Die Frau, ___ ich gestern gesehen habe, wohnt hier.",["der","die","das","den"],1,"Feminine accusative: die."],["Das Kind, ___ ich helfe, heißt Lena.",["das","dem","den","der"],1,"helfen takes dative; neuter: dem."],["Das ist das Haus, ___ ich wohne.",["in dem","in das","in der","in den"],0,"wohnen + in + dative; neuter: in dem."],["Die Kollegen, mit ___ ich arbeite, sind nett.",["die","denen","den","dem"],1,"mit + dative plural: denen."]],"table":[["","Nominativ","Akkusativ","Dativ"],["maskulin","der","den","dem"],["feminin","die","die","der"],["neutral","das","das","dem"],["Plural","die","die","denen"]]},{"id":"b1-konjunktiv2","level":"B1","title":"Konjunktiv II: Wünsche und Höflichkeit","en":"Subjunctive II for wishes and polite requests","intro":["Konjunktiv II expresses unreal situations, wishes and polite requests. For most verbs use würde + infinitive: Ich würde gern reisen. For sein, haben and the modals use their own forms: wäre, hätte, könnte, müsste, dürfte.","Unreal conditions: Wenn ich mehr Zeit hätte, würde ich mehr lesen. (I do not have time, so it is unreal.)","Politeness: Könnten Sie mir helfen? Ich hätte gern einen Kaffee."],"ex":[["Wenn ich Zeit hätte, würde ich reisen.","If I had time, I would travel."],["Ich wäre gern Arzt.","I would like to be a doctor."],["Könnten Sie mir bitte helfen?","Could you please help me?"],["An deiner Stelle würde ich das nicht tun.","In your place I would not do that."]],"q":[["Wenn ich reich ___, würde ich ein Haus kaufen.",["bin","war","wäre","wurde"],2,"Unreal condition: wäre."],["___ Sie mir bitte helfen?",["Können","Könnten","Konnten","Kann"],1,"Könnten is more polite."],["Ich ___ gern einen Tee. (haben, höflich)",["habe","hatte","hätte","würde haben"],2,"Ich hätte gern ... is the polite form."],["Wenn er mehr Zeit hätte, ___ er mehr lesen.",["würde","wird","wurde","werde"],0,"Result clause with würde + infinitive."],["Wenn ich du ___, würde ich zum Arzt gehen.",["bin","wäre","war","würde"],1,"wenn ich du wäre: fixed expression."]],"table":[["","sein","haben","können","werden"],["ich","wäre","hätte","könnte","würde"],["du","wärst","hättest","könntest","würdest"],["er/sie/es","wäre","hätte","könnte","würde"],["wir","wären","hätten","könnten","würden"]]},{"id":"b1-passiv","level":"B1","title":"Passiv Präsens","en":"Present passive","intro":["The passive focuses on the action, not on who does it. Form: werden (conjugated) + past participle at the end: Das Auto wird repariert.","The doer can be added with von + dative: Das Auto wird von dem Mechaniker repariert. In many sentences it is left out: Hier wird Deutsch gesprochen.","Active → passive: the object of the active sentence becomes the subject. Der Arzt untersucht den Patienten. → Der Patient wird (vom Arzt) untersucht."],"ex":[["Hier wird nicht geraucht.","There is no smoking here."],["Die Zähne werden gereinigt.","The teeth are cleaned."],["Das Formular wird online ausgefüllt.","The form is filled in online."],["Der Patient wird von der Ärztin untersucht.","The patient is examined by the doctor."]],"q":[["Das Büro ___ um 8 Uhr geöffnet.",["ist","wird","werden","hat"],1,"Passive: wird + participle."],["Die Rechnungen ___ per E-Mail geschickt.",["wird","werden","sind","wurde"],1,"Plural subject: werden."],["Der Patient wird ___ der Ärztin untersucht.",["von","durch","mit","bei"],0,"The doer is introduced with von."],["Hier ___ Deutsch gesprochen.",["wird","wirst","werden","werde"],0,"No explicit subject: wird."],["Active: 'Man baut ein Haus.' → Passive:",["Ein Haus wird gebaut.","Ein Haus ist gebaut.","Ein Haus baut.","Ein Haus wurde bauen."],0,"Subject + wird + past participle."]],"table":[["","werden"],["ich","werde"],["du","wirst"],["er/sie/es","wird"],["wir/sie/Sie","werden"],["ihr","werdet"]]},{"id":"b1-nebensaetze","level":"B1","title":"Nebensätze: obwohl, damit, um ... zu","en":"Subordinate clauses: although, so that, in order to","intro":["obwohl (although) expresses a contrast. damit (so that) and um ... zu (in order to) express a purpose.","Use um ... zu + infinitive when the subject is the same in both parts: Ich lerne Deutsch, um in Deutschland zu arbeiten. Use damit when the subjects differ: Ich spreche langsam, damit du mich verstehst.","In the subordinate clause the conjugated verb is at the end. With separable verbs zu goes between the prefix and the verb: um früh aufzustehen."],"ex":[["Obwohl es regnet, gehen wir spazieren.","Although it is raining, we go for a walk."],["Ich lerne Deutsch, um in Deutschland zu arbeiten.","I learn German in order to work in Germany."],["Sie erklärt es noch einmal, damit alle es verstehen.","She explains it again so that everybody understands."],["Er ging zum Arzt, ohne einen Termin zu haben.","He went to the doctor without having an appointment."]],"q":[["___ er krank ist, geht er zur Arbeit.",["Weil","Obwohl","Damit","Dass"],1,"Contrast: obwohl."],["Ich spare Geld, ___ ein Auto zu kaufen.",["damit","weil","um","obwohl"],2,"Same subject, purpose: um ... zu."],["Der Lehrer spricht langsam, ___ wir ihn verstehen.",["um","damit","obwohl","ohne"],1,"Different subjects: damit."],["Sie steht früh auf, um pünktlich ___.",["anzukommen","ankommen","zu ankommen","angekommen"],0,"Separable verb: an + zu + kommen = anzukommen."],["Obwohl ich müde ___, arbeite ich weiter.",["bin","ich bin","war ich","sein"],0,"Verb at the end of the obwohl-clause."]]}]}$j$::jsonb),
('grammar-b2', 'grammar', $j${"level":"B2","topics":[{"id":"b2-passiv2","level":"B2","title":"Passiv: Vergangenheit und Modalverben","en":"Passive in the past and with modal verbs","intro":["Präteritum passive: wurde + participle: Das Haus wurde 1990 gebaut. Perfekt passive: ist + participle + worden: Das Haus ist 1990 gebaut worden.","With a modal verb: modal + participle + werden: Das Formular muss ausgefüllt werden. Past: Das Formular musste ausgefüllt werden.","Careful: in the Perfekt passive the participle of werden is worden (not geworden)."],"ex":[["Die Brücke wurde 1998 eröffnet.","The bridge was opened in 1998."],["Der Patient ist gestern operiert worden.","The patient was operated on yesterday."],["Die Aufgabe muss bis Freitag erledigt werden.","The task has to be completed by Friday."],["Der Termin konnte nicht verschoben werden.","The appointment could not be postponed."]],"q":[["Das Gebäude ___ vor zehn Jahren gebaut.",["wird","wurde","ist","hat"],1,"Past passive: wurde + participle."],["Der Brief ist gestern geschickt ___.",["geworden","worden","wurde","werden"],1,"Perfekt passive ends in worden."],["Die Rechnung muss sofort bezahlt ___.",["werden","worden","wird","geworden"],0,"Modal + participle + werden (infinitive)."],["Die Operation ___ erfolgreich durchgeführt.",["wurde","wirst","hat","worden"],0,"Written past: wurde + participle."],["Der Fehler konnte nicht mehr korrigiert ___.",["wurden","werden","worden","wird"],1,"Modal in the past: konnte ... werden."]]},{"id":"b2-konjunktiv1","level":"B2","title":"Konjunktiv I: indirekte Rede","en":"Subjunctive I: reported speech","intro":["Reported speech (in news and formal writing) uses Konjunktiv I. Form: infinitive stem + -e, -est, -e, -en, -et, -en: er gehe, sie habe, er sei (irregular).","In practice you mostly see the er/sie/es form: er sage, sie komme, er habe, sie sei. If the Konjunktiv I form is identical to the normal present (ich/wir/sie plural), use Konjunktiv II or würde instead: Sie sagten, sie hätten keine Zeit.","Direct: Der Minister sagte: 'Wir haben das Problem gelöst.' Indirect: Der Minister sagte, man habe das Problem gelöst."],"ex":[["Er sagt, er habe keine Zeit.","He says he has no time."],["Sie erklärte, sie sei krank.","She explained she was ill."],["Der Arzt meint, der Patient müsse mehr trinken.","The doctor says the patient must drink more."],["Sie sagten, sie hätten alles verstanden.","They said they had understood everything."]],"q":[["Er sagte, er ___ müde.",["ist","sei","war","wird"],1,"Konjunktiv I of sein: er sei."],["Sie behauptet, sie ___ den Termin vergessen.",["hat","habe","hatte","haben"],1,"Konjunktiv I of haben: sie habe."],["Der Chef sagt, er ___ morgen. (kommen)",["kommt","komme","kam","kommen"],1,"Konjunktiv I: er komme."],["Sie sagten, sie ___ keine Zeit.",["haben","hätten","habe","hatten"],1,"Konjunktiv I (sie haben) looks like the normal present, so Konjunktiv II is used: hätten."],["Direkt: 'Ich bin krank.' Indirekt: Er sagt, er ___ krank.",["ist","sei","war","wird"],1,"er sei."]]},{"id":"b2-partizip","level":"B2","title":"Partizipien als Adjektive","en":"Participles as adjectives","intro":["Participle I (infinitive + d) is active and simultaneous: ein lächelnder Mann = a man who is smiling. Participle II is passive or completed: ein geschlossenes Fenster = a window that has been closed.","They take normal adjective endings: der schlafende Hund, die gestörte Ruhe, ein bekanntes Problem."],"ex":[["Das ist ein spannendes Buch.","That is an exciting book."],["Die gestohlene Tasche wurde gefunden.","The stolen bag was found."],["Der wartende Patient liest eine Zeitschrift.","The waiting patient reads a magazine."],["Ich kaufe ein gebrauchtes Auto.","I am buying a used car."]],"q":[["Der ___ Mann trägt einen Hut. (lächeln)",["lächelnde","gelächelte","lächelte","lächelnd"],0,"Active, happening now: Partizip I + e."],["Die ___ Tür steht offen. (öffnen: already opened)",["öffnende","geöffnete","öffnete","öffnet"],1,"Completed action: Partizip II + e."],["Die ___ Preise sind für viele zu hoch. (steigen: going up)",["gestiegenen","steigenden","gestiegende","steigen"],1,"Ongoing process: steigend + en."],["Das ___ Auto war billig. (benutzen: used)",["benutzende","benutzte","benutzt","benutzenden"],1,"Completed/passive: das benutzte Auto."],["Ein ___ Kind braucht Ruhe. (erschöpfen: exhausted)",["erschöpftes","erschöpfendes","erschöpfender","erschöpfte"],0,"Neuter after ein: Partizip II + es: ein erschöpftes Kind."]]},{"id":"b2-genitiv","level":"B2","title":"Genitiv und Präpositionen mit Genitiv","en":"Genitive and prepositions with the genitive","intro":["The genitive shows possession or relationship: das Auto des Mannes (the man's car). Masculine and neuter nouns add -s or -es: des Mannes, des Kindes. Feminine and plural: der Frau, der Kinder.","Common prepositions with the genitive (formal, written German): wegen (because of), trotz (despite), während (during), statt/anstatt (instead of), innerhalb (within), außerhalb (outside of). In speech the dative is often used instead, but in writing and exams use the genitive."],"ex":[["Wegen des Wetters bleiben wir zu Hause.","Because of the weather we stay at home."],["Trotz der Schmerzen ging er zur Arbeit.","Despite the pain he went to work."],["Während des Unterrichts darf man nicht telefonieren.","During class you may not use the phone."],["Das ist die Meinung des Arztes.","That is the doctor's opinion."]],"q":[["Wegen ___ Regens fällt das Spiel aus. (der Regen)",["der","dem","des","den"],2,"wegen + genitive; masculine: des Regens."],["Trotz ___ Krankheit arbeitet sie. (die Krankheit)",["die","der","dem","des"],1,"trotz + genitive; feminine: der Krankheit."],["Während ___ Urlaubs habe ich viel gelesen. (der Urlaub)",["des","dem","der","den"],0,"während + genitive; masculine: des Urlaubs."],["Das ist das Auto ___ Nachbarn. (der Nachbar)",["der","den","des","dem"],2,"Possession: des Nachbarn (weak masculine ending -n)."],["Statt ___ Kaffees trinke ich Tee. (der Kaffee)",["den","dem","des","der"],2,"statt + genitive: des Kaffees."]],"table":[["","Genitiv"],["maskulin","des Mannes"],["feminin","der Frau"],["neutral","des Kindes"],["Plural","der Kinder"]]},{"id":"b2-nominal","level":"B2","title":"Nomen-Verb-Verbindungen","en":"Noun-verb combinations","intro":["In formal German many verbs are replaced by a fixed combination of a noun and a verb with a general meaning. The meaning is the same as the single verb, but the style is more formal.","Learn them as fixed phrases with the preposition and case: eine Entscheidung treffen (= entscheiden), Kritik üben an (+ Dativ) (= kritisieren), in Frage stellen (= bezweifeln), zur Verfügung stellen (= bereitstellen)."],"ex":[["Wir müssen eine Entscheidung treffen.","We have to make a decision."],["Er übt scharfe Kritik an der Regierung.","He sharply criticises the government."],["Die Firma stellt den Mitarbeitern ein Auto zur Verfügung.","The company provides employees with a car."],["Ich nehme Rücksicht auf meine Kollegen.","I show consideration for my colleagues."]],"q":[["eine Entscheidung ___",["machen","treffen","geben","nehmen"],1,"The fixed phrase is: eine Entscheidung treffen."],["Kritik ___ an (jemandem/etwas)",["machen","geben","üben","treffen"],2,"Kritik üben an + dative."],["Das Ergebnis wurde in Frage ___.",["gestellt","gelegt","gesetzt","gegeben"],0,"in Frage stellen."],["Ich ___ Rücksicht auf meine Familie.",["habe","mache","nehme","gebe"],2,"Rücksicht nehmen auf + accusative."],["Die Klinik stellt den Patienten Informationen ___ Verfügung.",["in","zur","bei","an"],1,"zur Verfügung stellen."]]},{"id":"b2-konnektoren","level":"B2","title":"Konnektoren: deshalb, trotzdem, außerdem, dennoch","en":"Connectors","intro":["Some connectors (adverbs) take position 1 and push the verb to position 2: Es regnet. Deshalb bleibe ich zu Hause. (Not: Deshalb ich bleibe.)","deshalb / deswegen / daher = therefore. trotzdem / dennoch = nevertheless. außerdem = in addition. allerdings = however. sonst = otherwise. Und, aber, oder, denn, sondern do not change the word order: Ich bin müde, aber ich arbeite weiter."],"ex":[["Ich bin erkältet. Deshalb bleibe ich im Bett.","I have a cold. Therefore I stay in bed."],["Es regnet, trotzdem gehen wir spazieren.","It is raining; nevertheless we go for a walk."],["Er ist nett. Außerdem ist er sehr klug.","He is nice. In addition he is very clever."],["Beeil dich, sonst verpassen wir den Zug.","Hurry up, otherwise we will miss the train."]],"q":[["Ich habe Hunger. ___ koche ich etwas.",["Deshalb","Obwohl","Weil","Dass"],0,"Result: deshalb."],["Er war müde. ___ ging er noch zur Arbeit.",["Deshalb","Trotzdem","Weil","Damit"],1,"Contrast: trotzdem."],["Es regnet. Deshalb ___ ich zu Hause.",["bleibe","ich bleibe","bleiben","geblieben"],0,"After deshalb the verb comes next: Deshalb bleibe ich."],["Das Hotel ist günstig. ___ liegt es zentral.",["Weil","Außerdem","Dass","Obwohl"],1,"Adding a point: außerdem."],["Lern jetzt, ___ fällst du durch die Prüfung.",["sonst","deshalb","trotzdem","außerdem"],0,"Otherwise: sonst."]]}]}$j$::jsonb),
('grammar-c1', 'grammar', $j${"level":"C1","topics":[{"id":"c1-konj2-past","level":"C1","title":"Konjunktiv II der Vergangenheit","en":"Past subjunctive II","intro":["To talk about unreal things in the past (what would have happened), use hätte/wäre + past participle: Wenn ich mehr gelernt hätte, hätte ich die Prüfung bestanden.","Use wäre with verbs that form the Perfekt with sein (gehen, kommen, fahren): Wenn ich früher gekommen wäre, ... Modal verbs: Ich hätte kommen können / Ich hätte lernen müssen.","Regrets and criticism: Du hättest mich anrufen sollen. I wish...: Hätte ich doch mehr Zeit gehabt!"],"ex":[["Wenn ich Zeit gehabt hätte, wäre ich gekommen.","If I had had time, I would have come."],["Wir hätten früher losfahren sollen.","We should have left earlier."],["Hättest du mir doch geholfen!","If only you had helped me!"],["Ohne deine Hilfe hätte ich es nicht geschafft.","Without your help I would not have managed."]],"q":[["Wenn er mehr gelernt ___, hätte er bestanden.",["hat","hätte","wäre","würde"],1,"lernen takes haben: hätte gelernt."],["Wenn wir den Zug nicht verpasst ___, wären wir pünktlich gewesen.",["hätten","wären","haben","würden"],0,"verpassen takes haben: hätten verpasst."],["Wenn sie früher ___ wäre, hätte sie ihn getroffen. (kommen)",["gekommen","kommen","gekomm","kam"],0,"wäre + gekommen."],["Du ___ mich anrufen sollen.",["hast","hättest","wärst","würdest"],1,"Criticism about the past: du hättest ... sollen."],["Ich hätte das nie ___ können.",["gedacht","denken","dachte","zu denken"],1,"With a modal: hätte + infinitive + können (double infinitive). Here: hätte denken können."]]},{"id":"c1-partizip-erweitert","level":"C1","title":"Erweitertes Partizipialattribut","en":"Extended participial attribute","intro":["Written German (news, science, law) packs a relative clause before a noun: Der Patient, der von der Ärztin untersucht wird → Der von der Ärztin untersuchte Patient.","Structure: article + extra information + participle (+ ending) + noun. Partizip I (-d) for active/simultaneous, Partizip II for passive/completed. To read it, find the article, then the participle just before the noun, and the information between them belongs to the participle.","Back-translate it into a relative clause: das im letzten Jahr eingeführte Gesetz = das Gesetz, das im letzten Jahr eingeführt wurde."],"ex":[["Die von der Regierung geplante Reform wird kritisiert.","The reform planned by the government is criticised."],["Der seit Jahren steigende Verkehr belastet die Stadt.","The traffic, which has been rising for years, burdens the city."],["Das im Jahr 2020 eingeführte Gesetz gilt noch.","The law introduced in 2020 still applies."],["Die auf dem Tisch liegenden Unterlagen sind wichtig.","The documents lying on the table are important."]],"q":[["Der Patient, der von der Ärztin untersucht wird → Der von der Ärztin ___ Patient",["untersuchende","untersuchte","untersuchten","untersucht"],1,"Passive, completed: untersuchte."],["Die Kinder, die auf dem Spielplatz spielen → Die auf dem Spielplatz ___ Kinder",["spielenden","gespielten","spielende","spielten"],0,"Active, simultaneous: Partizip I + plural ending -en."],["Das Gesetz, das letztes Jahr beschlossen wurde → Das letztes Jahr ___ Gesetz",["beschließende","beschlossene","beschlossen","beschließt"],1,"Passive: beschlossene."],["Die Zahl der Menschen, die Deutsch lernen, wächst → Die Zahl der Deutsch ___ Menschen wächst.",["lernenden","gelernten","gelernt","lernender"],0,"Active, plural genitive: lernenden."],["Das ___ Dokument muss unterschrieben werden. (das gestern per E-Mail geschickte)",["geschickende","geschickte","schickende","schickten"],1,"Passive/completed: geschickte; the whole: das gestern per E-Mail geschickte Dokument."]]},{"id":"c1-passiversatz","level":"C1","title":"Passiversatzformen","en":"Alternatives to the passive","intro":["Instead of the passive German often uses: (1) man + active verb: Man kann das lösen. (2) sich lassen + infinitive: Das lässt sich lösen (= can be solved). (3) sein + zu + infinitive: Das Problem ist zu lösen (= must/can be solved). (4) -bar/-lich adjectives: lösbar, erklärbar.","Sein + zu + infinitive can mean 'can be' (Das Problem ist leicht zu lösen) or 'must be' (Der Antrag ist bis Montag einzureichen)."],"ex":[["Das lässt sich leicht erklären.","That can easily be explained."],["Die Aufgabe ist in einer Stunde zu schaffen.","The task can be done in an hour."],["Die Unterlagen sind bis Freitag einzureichen.","The documents must be submitted by Friday."],["Diese Frage ist nicht zu beantworten.","This question cannot be answered."]],"q":[["Das Problem ___ sich nicht schnell lösen.",["lässt","lasst","lassen","ließ"],0,"sich lassen + infinitive: das lässt sich ... lösen."],["Der Antrag ist bis Montag ___. (einreichen)",["einzureichen","zu einreichen","einreichen zu","eingereicht"],0,"sein + zu + infinitive; separable verb: ein-zu-reichen."],["Diese Methode ___ sich leicht anwenden.",["lässt","wird","ist","kann"],0,"lässt sich: can be applied."],["Passiv: 'Das Zimmer kann nicht gebucht werden.' = Das Zimmer ist nicht ___.",["zu buchen","buchen","gebucht","buchend"],0,"sein + zu + infinitive = can/must be."],["Man kann das nicht erklären. = Das ist nicht ___.",["erklärbar","erklärend","erklärt","erklären"],0,"-bar expresses 'can be': erklärbar."]]},{"id":"c1-funktionsverb","level":"C1","title":"Funktionsverbgefüge","en":"Fixed noun-verb constructions","intro":["Functional verb constructions combine a noun (often derived from a verb) with a verb that has lost its main meaning. They are typical for official, academic and business German.","Examples: zur Sprache bringen (= ansprechen), in Betracht ziehen (= erwägen), Anspruch erheben auf (= beanspruchen), zum Ausdruck bringen (= ausdrücken), unter Beweis stellen (= beweisen), in Kauf nehmen (= akzeptieren), Bezug nehmen auf (= sich beziehen auf).","They often allow modification with adjectives (große Beachtung finden) and passive-like meaning (zur Anwendung kommen = wird angewendet)."],"ex":[["Er brachte das Problem in der Sitzung zur Sprache.","He raised the problem in the meeting."],["Wir ziehen mehrere Möglichkeiten in Betracht.","We are considering several options."],["Sie nahm die Nachteile in Kauf.","She accepted the disadvantages."],["Das Verfahren kommt seit 2020 zur Anwendung.","The procedure has been in use since 2020."]],"q":[["Er brachte seine Kritik deutlich zum ___.",["Ausdruck","Sprechen","Sagen","Zeigen"],0,"zum Ausdruck bringen."],["Wir müssen alle Möglichkeiten in ___ ziehen.",["Betracht","Gedanken","Frage","Sicht"],0,"in Betracht ziehen."],["Die Firma nahm hohe Kosten in ___.",["Kauf","Gebühr","Rechnung","Gang"],0,"in Kauf nehmen."],["Sie stellte ihr Können unter ___.",["Beweis","Prüfung","Kontrolle","Wert"],0,"unter Beweis stellen."],["Ich nehme ___ auf Ihr Schreiben vom 3. Mai.",["Bezug","Beziehung","Verbindung","Hinweis"],0,"Bezug nehmen auf."]]},{"id":"c1-doppel","level":"C1","title":"Doppelkonnektoren und als ob","en":"Paired connectors and 'as if'","intro":["Paired connectors: nicht nur ... sondern auch (not only ... but also), sowohl ... als auch (both ... and), entweder ... oder (either ... or), weder ... noch (neither ... nor), zwar ... aber (admittedly ... but), je ... desto (the more ... the more).","With weder ... noch the sentence has no further negation: Er hat weder Zeit noch Lust. With je ... desto/umso, both parts use the comparative: Je mehr du übst, desto besser wirst du.","als ob / als wenn + Konjunktiv II expresses a comparison with something unreal: Er tut so, als ob er alles wüsste. Also possible with als + inverted verb: Er tut so, als wüsste er alles."],"ex":[["Sie spricht nicht nur Deutsch, sondern auch Arabisch.","She speaks not only German but also Arabic."],["Er hat weder Zeit noch Geld.","He has neither time nor money."],["Je länger ich lerne, desto besser verstehe ich.","The longer I study, the better I understand."],["Er tut so, als ob er krank wäre.","He acts as if he were ill."]],"q":[["Das Hotel ist nicht nur günstig, ___ auch sauber.",["aber","sondern","und","oder"],1,"nicht nur ... sondern auch."],["Er kommt ___ heute oder morgen.",["entweder","weder","sowohl","nicht nur"],0,"entweder ... oder."],["Er hat ___ angerufen noch geschrieben.",["entweder","weder","sowohl","nicht"],1,"weder ... noch."],["Je mehr du übst, ___ besser wirst du.",["je","desto","als","so"],1,"je ... desto + comparative."],["Sie tut so, als ob sie nichts ___.",["weiß","wüsste","wissen","gewusst"],1,"als ob + Konjunktiv II: wüsste."]]}]}$j$::jsonb)
on conflict (key) do update set kind = excluded.kind, payload = excluded.payload;
